// Gives every CSS Module a typed list of its class names, so a misspelled `styles.titel` is a compile error and not a
// silently missing style. For `Foo.module.css` it writes `Foo.module.d.css.ts` next to it (the file name TypeScript
// looks for with `allowArbitraryExtensions`). The generated files are not committed.
//
// Used two ways: `npm run css-types` (also part of typecheck and build) and as a Vite plugin while the dev server runs.

import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const HEADER = '// Generated by tools/css-module-types.ts from the matching .module.css file. Do not edit; not committed.\n';

/** Every class name used in a stylesheet, sorted. */
export function classNamesIn(css: string): string[] {
  const stripped = css
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/url\([^)]*\)/g, '')
    .replace(/"[^"]*"|'[^']*'/g, '');
  const names = new Set<string>();
  for (const match of stripped.matchAll(/\.(-?[_a-zA-Z][\w-]*)/g)) {
    const name = match[1];
    if (name !== undefined) {
      names.add(name);
    }
  }
  return [...names].sort();
}

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;

export function declarationFor(css: string): string {
  const members = classNamesIn(css).map((name) => `  readonly ${IDENTIFIER.test(name) ? name : JSON.stringify(name)}: string;`);
  return `${HEADER}declare const styles: {\n${members.join('\n')}\n};\nexport default styles;\n`;
}

export function declarationPathFor(cssFile: string): string {
  return cssFile.replace(/\.module\.css$/, '.module.d.css.ts');
}

/** Writes the declaration for one stylesheet. Returns false when it was already up to date. */
export function writeDeclaration(cssFile: string): boolean {
  const target = declarationPathFor(cssFile);
  const next = declarationFor(readFileSync(cssFile, 'utf8'));
  if (existsSync(target) && readFileSync(target, 'utf8') === next) {
    return false;
  }
  writeFileSync(target, next, 'utf8');
  return true;
}

/** Writes the declarations for every `.module.css` under a folder. Returns how many files were written. */
export function writeAllDeclarations(folder: string): number {
  let written = 0;
  for (const name of readdirSync(folder)) {
    const full = join(folder, name);
    if (statSync(full).isDirectory()) {
      written += writeAllDeclarations(full);
    } else if (name.endsWith('.module.css') && writeDeclaration(full)) {
      written += 1;
    }
  }
  return written;
}
